package engine

// Golden command fixtures: testdata/cases.json. Cases with "source":
// "python" carry the verdict the Python git-guard returns for the same
// command and fake repository (generated by running scripts/gitguard through
// tests/helpers.py); "source": "go" cases cover Go-only behaviour (ID006)
// with hand-written expectations. The file doubles as the guard's golden
// payloads.

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/nnminh-sam/agentic-workflows/plugins/my-git/cli/internal/shell"
	"github.com/nnminh-sam/agentic-workflows/plugins/my-git/cli/internal/verdict"
)

// GoldenCase is one entry of testdata/cases.json.
type GoldenCase struct {
	Name     string                     `json:"name"`
	Command  string                     `json:"command"`
	Dialect  string                     `json:"dialect"`
	Cwd      string                     `json:"cwd,omitempty"`
	Profile  string                     `json:"profile"` // default | gh | none
	Vars     map[string]any             `json:"vars,omitempty"`
	Repo     map[string]json.RawMessage `json:"repo,omitempty"` // FakeRunner kwargs; null = unset
	Env      map[string]string          `json:"env,omitempty"`
	Files    map[string]string          `json:"files,omitempty"`
	Decision verdict.Decision           `json:"decision"`
	Rules    []string                   `json:"rules"`
	Source   string                     `json:"source"`
}

func loadGolden(t testing.TB) []GoldenCase {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "cases.json"))
	if err != nil {
		t.Fatal(err)
	}
	var cases []GoldenCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}
	return cases
}

// goldenRepo builds the fake repository from FakeRunner kwargs.
func goldenRepo(t testing.TB, kw map[string]json.RawMessage) *fakeRepo {
	r := newFake()
	str := func(raw json.RawMessage) (string, bool) {
		var s *string
		if err := json.Unmarshal(raw, &s); err != nil {
			t.Fatalf("repo value %s: %v", raw, err)
		}
		if s == nil {
			return "", false
		}
		return *s, true
	}
	setCfg := func(key string, raw json.RawMessage) {
		if s, ok := str(raw); ok {
			r.config[key] = s
		} else {
			delete(r.config, key)
		}
	}
	for k, raw := range kw {
		switch k {
		case "name":
			setCfg("user.name", raw)
		case "email":
			setCfg("user.email", raw)
		case "ssh":
			setCfg("core.sshCommand", raw)
		case "helper":
			setCfg("credential.helper", raw)
		case "gh_login":
			r.ghLogin, _ = str(raw)
		case "branch":
			r.branch, _ = str(raw)
		case "remotes":
			r.remotes = map[string]string{}
			if err := json.Unmarshal(raw, &r.remotes); err != nil {
				t.Fatal(err)
			}
		case "has_commits":
			if err := json.Unmarshal(raw, &r.hasCommits); err != nil {
				t.Fatal(err)
			}
		case "remote_branches":
			var bs []string
			if err := json.Unmarshal(raw, &bs); err != nil {
				t.Fatal(err)
			}
			r.remoteBranches = map[string]bool{}
			for _, b := range bs {
				r.remoteBranches[b] = true
			}
		case "config":
			var m map[string]*string
			if err := json.Unmarshal(raw, &m); err != nil {
				t.Fatal(err)
			}
			for ck, cv := range m {
				if cv == nil {
					delete(r.config, ck)
				} else {
					r.config[ck] = *cv
				}
			}
		default:
			t.Fatalf("unknown repo key %q", k)
		}
	}
	return r
}

func goldenOpts(t testing.TB, c GoldenCase) opts {
	var vars map[string]any
	switch c.Profile {
	case "", "default":
		vars = testProfile()
	case "gh":
		vars = ghProfile()
	case "none":
		vars = map[string]any{}
	default:
		t.Fatalf("unknown profile %q", c.Profile)
	}
	o := opts{
		repo:  goldenRepo(t, c.Repo),
		pol:   testPolicy(t, withVars(vars, c.Vars), nil),
		files: c.Files,
		cwd:   c.Cwd,
	}
	if len(c.Env) > 0 {
		o.env = c.Env
	}
	if c.Dialect == "powershell" {
		o.dialect = shell.PowerShell
	}
	return o
}

func TestGoldenCases(t *testing.T) {
	cases := loadGolden(t)
	if len(cases) < 40 {
		t.Fatalf("only %d golden cases", len(cases))
	}
	seen := map[string]bool{}
	for _, c := range cases {
		if seen[c.Name] {
			t.Errorf("duplicate case name %q", c.Name)
		}
		seen[c.Name] = true
		t.Run(c.Name, func(t *testing.T) {
			v := run(t, c.Command, goldenOpts(t, c))
			want := c.Rules
			if want == nil {
				want = []string{}
			}
			if v.Decision() != c.Decision || !reflect.DeepEqual(ids(v), want) {
				t.Errorf("%s case %q (%s):\n  got  %s %v\n  want %s %v\n%s",
					c.Source, c.Command, c.Dialect, v.Decision(), ids(v), c.Decision, want, v.Reason())
			}
		})
	}
}
